166→		// supportedMech 只在第一次回应时携带（RFC 4178 §4.2.2）。
167→		mech = oidNTLMSSP
168→		c.mechSent = true
169→	}
170→	return NegTokenResp(state, mech, ntlm, nil)
171→}
172→
173→// handleNegotiate 处理 Type 1，生成 Type 2 CHALLENGE。
174→func (c *ntlmContext) handleNegotiate(msg []byte) ([]byte, bool, error) {
175→	neg, err := ParseNegotiateMessage(msg)
176→	if err != nil {
177→		return nil, false, err
178→	}
179→	c.negotiateMsg = append([]byte(nil), msg...)
180→
181→	if _, err := io.ReadFull(c.p.opts.Rand, c.serverChallenge[:]); err != nil {
182→		return nil, false, err
183→	}
184→
185→	ch := &ChallengeMessage{
186→		TargetName:      c.p.opts.ServerName,
187→		Flags:           c.challengeFlags(neg.Flags),
188→		ServerChallenge: c.serverChallenge,
189→		TargetInfo:      c.targetInfo(),
190→		Version: Version{
191→			// 宣告一个通用的现代版本号，只影响客户端的展示与兼容分支。
192→			Major: 6, Minor: 1, Build: 7601, NTLMRevision: NTLMRevisionCurrent,
193→		},
194→	}
195→	c.challengeMsg = ch.Marshal()
196→	return c.wrap(NegAcceptIncomplete, c.challengeMsg), false, nil
197→}
198→
199→// challengeFlags 计算 CHALLENGE 里回给客户端的协商标志。
200→//
201→// 原则：只保留双方都支持的位，并强制打开 NTLMv2 必需的
202→// EXTENDED_SESSIONSECURITY / TARGET_INFO / ALWAYS_SIGN。
203→func (c *ntlmContext) challengeFlags(client NegotiateFlags) NegotiateFlags {
204→	f := NegotiateNTLM |
205→		NegotiateRequestTarget |
206→		NegotiateTargetTypeServer |
207→		NegotiateTargetInfo |
208→		NegotiateAlwaysSign |
209→		NegotiateExtendedSessionSecurity |
210→		NegotiateVersion |
211→		Negotiate128 |
212→		Negotiate56
213→
214→	// 字符集：优先 Unicode。
215→	if client.Has(NegotiateUnicode) || !client.Has(NegotiateOEM) {
216→		f |= NegotiateUnicode
217→	} else {
218→		f |= NegotiateOEM
219→	}
220→
221→	// 这些位必须**镜像客户端的请求**，否则密钥协商会不一致。
222→	for _, bit := range []NegotiateFlags{
223→		NegotiateSign, NegotiateSeal, NegotiateKeyExch, NegotiateIdentify,
224→	} {
225→		if client.Has(bit) {
226→			f |= bit
227→		}
228→	}
229→	return f
230→}
231→
232→// targetInfo 构造 CHALLENGE 的 TargetInfo。
233→//
234→// MS-NLMP §2.2.2.1：前四项（NbDomainName / NbComputerName /
235→// DnsDomainName / DnsComputerName）不全时部分 Windows 客户端会拒绝，
236→// 因此一律带齐，并附上 Timestamp（NTLMv2 需要它来做重放窗口判断）。
237→func (c *ntlmContext) targetInfo() AvPairs {
238→	o := &c.p.opts
239→	return AvPairs{
240→		{ID: MsvAvNbDomainName, Value: utf16le(o.DomainName)},
241→		{ID: MsvAvNbComputerName, Value: utf16le(o.ServerName)},
242→		{ID: MsvAvDnsDomainName, Value: utf16le(o.DNSDomainName)},
243→		{ID: MsvAvDnsComputerName, Value: utf16le(o.DNSComputerName)},
244→		{ID: MsvAvTimestamp, Value: encodeFiletime(filetimeNow(o.Now()))},
245→	}
246→}
247→
248→// handleAuthenticate 处理 Type 3，完成校验。
249→func (c *ntlmContext) handleAuthenticate(msg []byte) ([]byte, bool, error) {
250→	m, err := ParseAuthenticateMessage(msg)
251→	if err != nil {
252→		return nil, false, err
253→	}
254→	if c.challengeMsg == nil {
255→		// 没发过 CHALLENGE 就收到 AUTHENTICATE，状态机被跳步。
256→		return nil, false, ErrInvalidToken
257→	}
258→
259→	if m.IsAnonymous() {
260→		if !c.p.opts.AllowAnonymous {
261→			return nil, false, ErrLogonFailure
262→		}
263→		c.identity = &Identity{Workstation: m.Workstation, Anonymous: true}
264→		c.sessionKey = make([]byte, SessionKeyLen)
265→		c.done = true
266→		return c.wrap(NegAcceptCompleted, nil), true, nil
267→	}
268→
269→	acct, lookupErr := c.lookup(m.UserName, m.DomainName)
270→
271→	// 用户不存在时也走一遍等价耗时的校验，避免用户枚举（provider.go 的要求）。
272→	ntHash := acct.NTHash
273→	ntowf := NTOWFv2(ntHash, m.UserName, m.DomainName)
274→	sbk, blob, ok := VerifyNTLMv2(ntowf, c.serverChallenge, m.NTResponse)
275→	if lookupErr != nil {
276→		ok = false
277→	}
278→
279→	if !ok {
280→		if c.p.opts.Store != nil && c.p.opts.Store.AllowGuest() {
281→			// 降级为 guest：没有可用的 session key，会话不能签名。
282→			c.identity = &Identity{
283→				User:        m.UserName,
284→				Domain:      m.DomainName,
285→				Workstation: m.Workstation,
286→				Guest:       true,
287→			}
288→			c.sessionKey = make([]byte, SessionKeyLen)
289→			c.done = true
290→			return c.wrap(NegAcceptCompleted, nil), true, nil
291→		}
292→		return nil, false, ErrLogonFailure
293→	}
294→
295→	esk, err := ExportedSessionKey(KeyExchangeKey(sbk), m.Flags, m.EncryptedRandomSessionKey)
296→	if err != nil {
297→		return nil, false, err
298→	}
299→
300→	if err := c.verifyMIC(m, blob, esk); err != nil {
301→		return nil, false, err
302→	}
303→
304→	c.identity = &Identity{
305→		User:        acct.User,
306→		Domain:      m.DomainName,
307→		Workstation: m.Workstation,
308→		UID:         acct.UID,
309→		GID:         acct.GID,
310→	}
311→	c.sessionKey = append([]byte(nil), esk[:]...)
312→	c.done = true
313→
314→	// TODO: 待验证 —— 客户端携带 mechListMIC 时，RFC 4178 §5 要求服务端在
315→	// 最终 negTokenResp 里回一个用 NTLM GSS_GetMIC 生成的 mechListMIC。
316→	// smbclient / Windows / macOS 在不回的情况下均能完成认证（SMB 签名本身
317→	// 已覆盖后续报文完整性），故暂不实现。
318→	return c.wrap(NegAcceptCompleted, nil), true, nil
319→}
320→
321→// dummyAccount 用于用户不存在时的等时校验，NTHash 恒为零值。
322→var dummyAccount = &Account{}
323→
324→func (c *ntlmContext) lookup(user, domain string) (*Account, error) {
325→	if c.p.opts.Store == nil {
326→		return dummyAccount, ErrNoSuchUser
327→	}
328→	acct, err := c.p.opts.Store.Lookup(user, domain)
329→	if err != nil || acct == nil {
330→		return dummyAccount, ErrNoSuchUser
331→	}
332→	return acct, nil
333→}
334→
335→// verifyMIC 在客户端声明带 MIC 时校验它（MS-NLMP §3.2.5.1.2）。
336→//
337→// MsvAvFlags 的 0x00000002 位置位表示 AUTHENTICATE_MESSAGE 里有 MIC，
338→// 此时服务端**必须**校验，否则中间人可以篡改 NEGOTIATE 里的标志位降级。
339→func (c *ntlmContext) verifyMIC(m *AuthenticateMessage, blob []byte, esk [16]byte) error {
340→	// blob 布局（MS-NLMP §2.2.2.7 NTLMv2_CLIENT_CHALLENGE）：
341→	// RespType(1) HiRespType(1) Z(2) Z(4) Timestamp(8) ClientChallenge(8) Z(4) AvPairs
342→	const clientChallengeHeader = 28
343→	if len(blob) < clientChallengeHeader {
344→		return nil // 不是 NTLMv2 blob（LMv2-only 之类），没有 AV_PAIR 可看
345→	}
346→	avs, err := ParseAvPairs(blob[clientChallengeHeader:])
347→	if err != nil {
348→		return ErrInvalidToken
349→	}
350→	v, ok := avs.Get(MsvAvFlags)
351→	if !ok || len(v) < 4 {
352→		return nil
353→	}
354→	flags := uint32(v[0]) | uint32(v[1])<<8 | uint32(v[2])<<16 | uint32(v[3])<<24
355→	if flags&AvFlagMICPresent == 0 {
356→		return nil
357→	}
358→	if !m.MICPresent {
359→		// 声明有 MIC 却没有字段 —— 拒绝，不能当作没带处理。
360→		return ErrLogonFailure
361→	}
362→	want := ComputeMIC(esk, c.negotiateMsg, c.challengeMsg, m.rawWithZeroMIC())
363→	if subtle.ConstantTimeCompare(want[:], m.MIC[:]) != 1 {
364→		return ErrLogonFailure
365→	}
366→	return nil
367→}
368→
369→// ServerChallenge 返回本次握手使用的 8 字节服务端质询（供日志/测试）。
370→func (c *ntlmContext) ServerChallenge() [8]byte { return c.serverChallenge }
