output.text:
  1→package auth
  2→
  3→// SPNEGO（RFC 4178）与 GSS-API InitialContextToken（RFC 2743 §3.1）编解码。
  4→//
  5→// 只实现 SMB2 认证需要的最小子集：服务端发 negTokenInit2 宣告支持 NTLMSSP，
  6→// 之后用裸 negTokenResp 交换 NTLM token。
  7→//
  8→// 这里手写 DER 的原因（AGENTS.md §4）：
  9→//   - `negHints` 里的 `GeneralString` 标准库 encoding/asn1 **无法 Marshal**
 10→//     （golang/go#18832），必须硬编码 tag 0x1B；
 11→//   - SPNEGO 大量使用 context-specific 构造标签，用标准库反射式 API 反而更绕。
 12→//
 13→// 解析一律**先校验长度再切片**，任何畸形输入返回 ErrInvalidToken，绝不 panic。
 14→
 15→import "errors"
 16→
 17→// ASN.1 tag（DER）。
 18→const (
 19→	tagOID          = 0x06
 20→	tagOctetString  = 0x04
 21→	tagEnumerated   = 0x0A
 22→	tagGeneralStr   = 0x1B // GeneralString，标准库编不出来
 23→	tagSequence     = 0x30 // SEQUENCE, constructed
 24→	tagApplication0 = 0x60 // [APPLICATION 0] constructed —— GSS InitialContextToken
 25→	tagContext0     = 0xA0 // [0] constructed
 26→	tagContext1     = 0xA1
 27→	tagContext2     = 0xA2
 28→	tagContext3     = 0xA3
 29→)
 30→
 31→// OID 的 DER content（不含 tag 与长度）。
 32→var (
 33→	// oidSPNEGO 是 1.3.6.1.5.5.2。
 34→	oidSPNEGO = []byte{0x2b, 0x06, 0x01, 0x05, 0x05, 0x02}
 35→	// oidNTLMSSP 是 1.3.6.1.4.1.311.2.2.10。
 36→	oidNTLMSSP = []byte{0x2b, 0x06, 0x01, 0x04, 0x01, 0x82, 0x37, 0x02, 0x02, 0x0a}
 37→	// oidKerberos5 是 1.2.840.113554.1.2.2，客户端常把它排在 mechTypes 首位。
 38→	oidKerberos5 = []byte{0x2a, 0x86, 0x48, 0x86, 0xf7, 0x12, 0x01, 0x02, 0x02}
 39→	// oidMSKerberos5 是 1.2.840.48018.1.2.2（微软的 legacy Kerberos OID）。
 40→	oidMSKerberos5 = []byte{0x2a, 0x86, 0x48, 0x82, 0xf7, 0x12, 0x01, 0x02, 0x02}
 41→)
 42→
 43→// negHintName 是 Windows 服务端在 negTokenInit2 里放的固定 hint 字符串。
 44→// 客户端会忽略它，但缺了它某些客户端（老 macOS）会不高兴。
 45→const negHintName = "not_defined_in_RFC4178@please_ignore"
 46→
 47→// NegState 是 RFC 4178 §4.2.2 的 negState。
 48→type NegState int
 49→
 50→const (
 51→	NegAcceptCompleted  NegState = 0
 52→	NegAcceptIncomplete NegState = 1
 53→	NegReject           NegState = 2
 54→	NegRequestMIC       NegState = 3
 55→)
 56→
 57→// ErrDER 表示 DER 结构非法。对外统一暴露为 ErrInvalidToken。
 58→var errDER = errors.New("auth: malformed DER")
 59→
 60→// ---------------------------------------------------------------- DER 编码
 61→
 62→// derLen 编码 DER 长度（短型 / 长型）。
 63→func derLen(n int) []byte {
 64→	switch {
 65→	case n < 0x80:
 66→		return []byte{byte(n)}
 67→	case n <= 0xFF:
 68→		return []byte{0x81, byte(n)}
 69→	case n <= 0xFFFF:
 70→		return []byte{0x82, byte(n >> 8), byte(n)}
 71→	default:
 72→		return []byte{0x83, byte(n >> 16), byte(n >> 8), byte(n)}
 73→	}
 74→}
 75→
 76→// derTLV 包一层 tag + 长度 + 内容。
 77→func derTLV(tag byte, content []byte) []byte {
 78→	l := derLen(len(content))
 79→	out := make([]byte, 0, 1+len(l)+len(content))
 80→	out = append(out, tag)
 81→	out = append(out, l...)
 82→	return append(out, content...)
 83→}
 84→
 85→// ---------------------------------------------------------------- DER 解析
 86→
 87→// derNext 从 b 中读出一个 TLV，返回 tag、内容与剩余字节。
 88→func derNext(b []byte) (tag byte, content, rest []byte, err error) {
 89→	if len(b) < 2 {
 90→		return 0, nil, nil, errDER
 91→	}
 92→	tag = b[0]
 93→	// 多字节 tag（0x1F）在 SPNEGO 里不会出现，直接拒绝。
 94→	if tag&0x1F == 0x1F {
 95→		return 0, nil, nil, errDER
 96→	}
 97→	i := 1
 98→	l := int(b[i])
 99→	i++
100→	if l&0x80 != 0 {
101→		n := l & 0x7F
102→		// 长度域超过 4 字节说明是畸形或超大报文，拒绝。
103→		if n == 0 || n > 4 || len(b) < i+n {
104→			return 0, nil, nil, errDER
105→		}
106→		l = 0
107→		for j := 0; j < n; j++ {
108→			l = l<<8 | int(b[i+j])
109→		}
110→		i += n
111→		if l < 0 {
112→			return 0, nil, nil, errDER
113→		}
114→	}
115→	if l > len(b)-i {
116→		return 0, nil, nil, errDER
117→	}
118→	return tag, b[i : i+l], b[i+l:], nil
119→}
120→
121→// ---------------------------------------------------------------- negTokenInit2
122→
123→// NegTokenInit2 构造服务端在 SMB2 NEGOTIATE Response 里宣告的 SPNEGO token。
124→//
125→// 结构（RFC 2743 §3.1 + RFC 4178 §4.2.1 + MS-SPNG §2.2.1）：
126→//
127→//	[APPLICATION 0] IMPLICIT SEQUENCE {
128→//	    thisMech           OID 1.3.6.1.5.5.2
129→//	    innerContextToken  [0] NegTokenInit2 {
130→//	        mechTypes [0] SEQUENCE OF OID { NTLMSSP }
131→//	        negHints  [3] SEQUENCE { hintName [0] GeneralString }
132→//	    }
133→//	}
134→func NegTokenInit2(mechs [][]byte) []byte {
135→	var mechList []byte
136→	for _, m := range mechs {
137→		mechList = append(mechList, derTLV(tagOID, m)...)
138→	}
139→	mechTypes := derTLV(tagContext0, derTLV(tagSequence, mechList))
140→
141→	// negHints —— hintName 必须是 GeneralString（tag 0x1B），
142→	// 标准库 encoding/asn1 无法 Marshal，这里手工拼。
143→	hint := derTLV(tagContext0, derTLV(tagGeneralStr, []byte(negHintName)))
144→	negHints := derTLV(tagContext3, derTLV(tagSequence, hint))
145→
146→	inner := derTLV(tagContext0, derTLV(tagSequence, append(mechTypes, negHints...)))
147→
148→	body := append(derTLV(tagOID, oidSPNEGO), inner...)
149→	return derTLV(tagApplication0, body)
150→}
151→
152→// ---------------------------------------------------------------- negTokenResp
153→
154→// NegTokenResp 构造服务端回给客户端的 negTokenResp（裸 [1] 包裹，无 GSS 外壳）。
155→//
156→//	NegTokenResp ::= SEQUENCE {
157→//	    negState      [0] ENUMERATED OPTIONAL
158→//	    supportedMech [1] MechType    OPTIONAL
159→//	    responseToken [2] OCTET STRING OPTIONAL
160→//	    mechListMIC   [3] OCTET STRING OPTIONAL
161→//	}
162→//
163→// supportedMech 只在**第一次**回应时携带（RFC 4178 §4.2.2）；
164→// mech 传 nil 表示不带。
165→func NegTokenResp(state NegState, mech, responseToken, mechListMIC []byte) []byte {
166→	var body []byte
167→	body = append(body, derTLV(tagContext0, derTLV(tagEnumerated, []byte{byte(state)}))...)
168→	if len(mech) > 0 {
169→		body = append(body, derTLV(tagContext1, derTLV(tagOID, mech))...)
170→	}
171→	if len(responseToken) > 0 {
172→		body = append(body, derTLV(tagContext2, derTLV(tagOctetString, responseToken))...)
173→	}
174→	if len(mechListMIC) > 0 {
175→		body = append(body, derTLV(tagContext3, derTLV(tagOctetString, mechListMIC))...)
176→	}
177→	return derTLV(tagContext1, derTLV(tagSequence, body))
178→}
179→
180→// ---------------------------------------------------------------- 客户端 token 解析
181→
182→// SPNEGOToken 是从客户端 token 中提取出的信息。
183→type SPNEGOToken struct {
184→	// Raw 为 true 表示这是裸 NTLMSSP（没有 SPNEGO 外壳）。
185→	Raw bool
186→	// Init 为 true 表示这是 negTokenInit（客户端的第一个 token）。
187→	Init bool
188→	// MechTypes 是客户端 negTokenInit 里列出的机制 OID（DER content，不含 tag）。
189→	MechTypes [][]byte
190→	// MechTypesDER 是 mechTypes 字段 **[0] 内部那层 SEQUENCE 的完整 DER**，
191→	// 计算 mechListMIC 时需要原样使用（RFC 4178 §5）。
192→	MechTypesDER []byte
193→	// Token 是内层的 NTLM 消息（mechToken 或 responseToken 的内容）。
194→	Token []byte
195→	// MechListMIC 是客户端携带的 mechListMIC（可能为空）。
196→	MechListMIC []byte
197→	// State 是客户端 negTokenResp 里的 negState，未携带时为 -1。
198→	State NegState
199→}
200→
201→// HasMech 报告 mechTypes 里是否包含给定 OID。
202→func (t *SPNEGOToken) HasMech(oid []byte) bool {
203→	for _, m := range t.MechTypes {
204→		if len(m) == len(oid) && string(m) == string(oid) {
205→			return true
206→		}
207→	}
208→	return false
209→}
210→
211→// ParseSPNEGO 解析客户端送来的 GSS/SPNEGO token。
212→//
213→// 支持三种形态：
214→//  1. 裸 NTLMSSP（buffer 以 "NTLMSSP\0" 开头）—— 部分客户端与 SMB1 会这么发；
215→//  2. GSS InitialContextToken（0x60）包裹的 negTokenInit / negTokenInit2；
216→//  3. 裸 negTokenResp（0xA1）。
217→func ParseSPNEGO(in []byte) (*SPNEGOToken, error) {
218→	if len(in) == 0 {
219→		return nil, ErrInvalidToken
220→	}
221→	if IsNTLMSSP(in) {
222→		return &SPNEGOToken{Raw: true, Token: in, State: -1}, nil
223→	}
224→
225→	switch in[0] {
226→	case tagApplication0:
227→		return parseInitialContextToken(in)
228→	case tagContext1:
229→		return parseNegTokenResp(in)
230→	case tagContext0:
231→		// 少数实现直接发裸 negTokenInit（无 GSS 外壳）。
232→		t, content, _, err := derNext(in)
233→		if err != nil || t != tagContext0 {
234→			return nil, ErrInvalidToken
235→		}
236→		return parseNegTokenInitBody(content)
237→	default:
238→		return nil, ErrInvalidToken
239→	}
240→}
241→
242→func parseInitialContextToken(in []byte) (*SPNEGOToken, error) {
243→	tag, content, _, err := derNext(in)
244→	if err != nil || tag != tagApplication0 {
245→		return nil, ErrInvalidToken
246→	}
247→	// thisMech
248→	tag, oid, rest, err := derNext(content)
249→	if err != nil || tag != tagOID {
250→		return nil, ErrInvalidToken
251→	}
252→	if string(oid) != string(oidSPNEGO) {
253→		// 不是 SPNEGO（例如裸 Kerberos GSS token），我们不支持。
254→		return nil, ErrMechUnsupported
255→	}
256→	tag, inner, _, err := derNext(rest)
257→	if err != nil {
258→		return nil, ErrInvalidToken
259→	}
260→	switch tag {
261→	case tagContext0:
262→		return parseNegTokenInitBody(inner)
263→	case tagContext1:
264→		return parseNegTokenRespBody(inner)
265→	default:
266→		return nil, ErrInvalidToken
267→	}
268→}
269→
270→// parseNegTokenInitBody 解析 [0] 内部的 SEQUENCE。
271→func parseNegTokenInitBody(inner []byte) (*SPNEGOToken, error) {
272→	tag, seq, _, err := derNext(inner)
273→	if err != nil || tag != tagSequence {
274→		return nil, ErrInvalidToken
275→	}
276→	out := &SPNEGOToken{Init: true, State: -1}
277→	for len(seq) > 0 {
278→		var t byte
279→		var content []byte
280→		t, content, seq, err = derNext(seq)
281→		if err != nil {
282→			return nil, ErrInvalidToken
283→		}
284→		switch t {
285→		case tagContext0: // mechTypes
286→			mt, mtSeq, _, err := derNext(content)
287→			if err != nil || mt != tagSequence {
288→				return nil, ErrInvalidToken
289→			}
290→			// mechListMIC 的计算范围是这层 SEQUENCE 的完整 DER。
291→			out.MechTypesDER = derTLV(tagSequence, mtSeq)
292→			for len(mtSeq) > 0 {
293→				var ot byte
294→				var oid []byte
295→				ot, oid, mtSeq, err = derNext(mtSeq)
296→				if err != nil {
297→					return nil, ErrInvalidToken
298→				}
299→				if ot == tagOID {
300→					cp := make([]byte, len(oid))
301→					copy(cp, oid)
302→					out.MechTypes = append(out.MechTypes, cp)
303→				}
304→			}
305→		case tagContext2: // mechToken
306→			ot, tok, _, err := derNext(content)
307→			if err != nil || ot != tagOctetString {
308→				return nil, ErrInvalidToken
309→			}
310→			out.Token = tok
311→		case tagContext3:
312→			// negTokenInit 的 [3] 在 RFC 4178 里是 mechListMIC，
313→			// 但 MS-SPNG 的 negTokenInit2 把它用作 negHints。
314→			// 用内容的 tag 区分：OCTET STRING 才是 MIC。
315→			if ot, mic, _, err := derNext(content); err == nil && ot == tagOctetString {
316→				out.MechListMIC = mic
317→			}
318→		case tagContext1: // reqFlags，忽略
319→		}
320→	}
321→	return out, nil
322→}
323→
324→func parseNegTokenResp(in []byte) (*SPNEGOToken, error) {
325→	tag, content, _, err := derNext(in)
326→	if err != nil || tag != tagContext1 {
327→		return nil, ErrInvalidToken
328→	}
329→	return parseNegTokenRespBody(content)
330→}
331→
332→func parseNegTokenRespBody(inner []byte) (*SPNEGOToken, error) {
333→	tag, seq, _, err := derNext(inner)
334→	if err != nil || tag != tagSequence {
335→		return nil, ErrInvalidToken
336→	}
337→	out := &SPNEGOToken{State: -1}
338→	for len(seq) > 0 {
339→		var t byte
340→		var content []byte
341→		t, content, seq, err = derNext(seq)
342→		if err != nil {
343→			return nil, ErrInvalidToken
344→		}
345→		switch t {
346→		case tagContext0: // negState
347→			et, v, _, err := derNext(content)
348→			if err != nil || et != tagEnumerated || len(v) != 1 {
349→				return nil, ErrInvalidToken
350→			}
351→			out.State = NegState(v[0])
352→		case tagContext1: // supportedMech
353→			ot, oid, _, err := derNext(content)
354→			if err != nil || ot != tagOID {
355→				return nil, ErrInvalidToken
356→			}
357→			cp := make([]byte, len(oid))
358→			copy(cp, oid)
359→			out.MechTypes = append(out.MechTypes, cp)
360→		case tagContext2: // responseToken
361→			ot, tok, _, err := derNext(content)
362→			if err != nil || ot != tagOctetString {
363→				return nil, ErrInvalidToken
364→			}
365→			out.Token = tok
366→		case tagContext3: // mechListMIC
367→			ot, mic, _, err := derNext(content)
368→			if err != nil || ot != tagOctetString {
369→				return nil, ErrInvalidToken
370→			}
371→			out.MechListMIC = mic
372→		}
373→	}
374→	return out, nil
375→}
