  1→package auth
  2→
  3→// NTLM (NTLMSSP) 报文层 —— MS-NLMP。
  4→//
  5→// 全部字段一律 **小端**（MS-NLMP §2.2）。
  6→// 变长字段用 payload 三元组描述：Len(2) || MaxLen(2) || BufferOffset(4)，
  7→// 偏移相对**消息起点**。
  8→//
  9→// 本文件只做 []byte ↔ struct，不含任何状态与 IO（对应 AGENTS.md P1）。
 10→
 11→import (
 12→	"encoding/binary"
 13→	"errors"
 14→	"unicode/utf16"
 15→)
 16→
 17→// Signature 与消息类型（MS-NLMP §2.2.1）。
 18→var ntlmSignature = [8]byte{'N', 'T', 'L', 'M', 'S', 'S', 'P', 0}
 19→
 20→// MessageType（MS-NLMP §2.2.1）。
 21→const (
 22→	MsgTypeNegotiate    uint32 = 0x00000001
 23→	MsgTypeChallenge    uint32 = 0x00000002
 24→	MsgTypeAuthenticate uint32 = 0x00000003
 25→)
 26→
 27→// 各消息的固定头长度（不含 payload）。
 28→const (
 29→	// NEGOTIATE：Signature(8)+Type(4)+Flags(4)+Domain(8)+Workstation(8)+Version(8)
 30→	negotiateHeaderSize = 40
 31→	// CHALLENGE：Signature(8)+Type(4)+TargetName(8)+Flags(4)+ServerChallenge(8)
 32→	//            +Reserved(8)+TargetInfo(8)+Version(8)
 33→	challengeHeaderSize = 56
 34→	// AUTHENTICATE：Signature(8)+Type(4)+Lm(8)+Nt(8)+Domain(8)+User(8)
 35→	//               +Workstation(8)+EncryptedRandomSessionKey(8)+Flags(4)
 36→	//               = 64；再加 Version(8) = 72；再加 MIC(16) = 88。
 37→	authenticateMinSize     = 64
 38→	authenticateVersionSize = 72
 39→	authenticateMICSize     = 88
 40→	// MICSize 是 AUTHENTICATE 消息里 MIC 字段长度。
 41→	MICSize = 16
 42→	// micOffset 是 MIC 字段在 AUTHENTICATE 消息中的偏移。
 43→	micOffset = 72
 44→)
 45→
 46→// maxNTLMMessageSize 是可接受的单条 NTLM 消息上限（防御性资源限制，AGENTS.md §8）。
 47→const maxNTLMMessageSize = 64 * 1024
 48→
 49→// NegotiateFlags 是 NTLM 协商标志（MS-NLMP §2.2.2.5）。
 50→type NegotiateFlags uint32
 51→
 52→// NTLMSSP_NEGOTIATE_* （MS-NLMP §2.2.2.5，位序按规范的 A..W 反向排列后的数值）。
 53→const (
 54→	NegotiateUnicode                 NegotiateFlags = 0x00000001
 55→	NegotiateOEM                     NegotiateFlags = 0x00000002
 56→	NegotiateRequestTarget           NegotiateFlags = 0x00000004
 57→	NegotiateSign                    NegotiateFlags = 0x00000010
 58→	NegotiateSeal                    NegotiateFlags = 0x00000020
 59→	NegotiateDatagram                NegotiateFlags = 0x00000040
 60→	NegotiateLMKey                   NegotiateFlags = 0x00000080
 61→	NegotiateNTLM                    NegotiateFlags = 0x00000200
 62→	NegotiateAnonymous               NegotiateFlags = 0x00000800
 63→	NegotiateOEMDomainSupplied       NegotiateFlags = 0x00001000
 64→	NegotiateOEMWorkstationSupplied  NegotiateFlags = 0x00002000
 65→	NegotiateAlwaysSign              NegotiateFlags = 0x00008000
 66→	NegotiateTargetTypeDomain        NegotiateFlags = 0x00010000
 67→	NegotiateTargetTypeServer        NegotiateFlags = 0x00020000
 68→	NegotiateExtendedSessionSecurity NegotiateFlags = 0x00080000
 69→	NegotiateIdentify                NegotiateFlags = 0x00100000
 70→	RequestNonNTSessionKey           NegotiateFlags = 0x00400000
 71→	NegotiateTargetInfo              NegotiateFlags = 0x00800000
 72→	NegotiateVersion                 NegotiateFlags = 0x02000000
 73→	Negotiate128                     NegotiateFlags = 0x20000000
 74→	NegotiateKeyExch                 NegotiateFlags = 0x40000000
 75→	Negotiate56                      NegotiateFlags = 0x80000000
 76→)
 77→
 78→// Has 报告是否置了给定标志位。
 79→func (f NegotiateFlags) Has(x NegotiateFlags) bool { return f&x != 0 }
 80→
 81→// AvID 是 AV_PAIR 的标识（MS-NLMP §2.2.2.1）。
 82→type AvID uint16
 83→
 84→const (
 85→	MsvAvEOL             AvID = 0x0000
 86→	MsvAvNbComputerName  AvID = 0x0001
 87→	MsvAvNbDomainName    AvID = 0x0002
 88→	MsvAvDnsComputerName AvID = 0x0003
 89→	MsvAvDnsDomainName   AvID = 0x0004
 90→	MsvAvDnsTreeName     AvID = 0x0005
 91→	MsvAvFlags           AvID = 0x0006
 92→	MsvAvTimestamp       AvID = 0x0007
 93→	MsvAvSingleHost      AvID = 0x0008
 94→	MsvAvTargetName      AvID = 0x0009
 95→	MsvAvChannelBindings AvID = 0x000A
 96→)
 97→
 98→// MsvAvFlags 的位（MS-NLMP §2.2.2.1）。
 99→const (
100→	// AvFlagConstrainedAuth：账户认证受限。
101→	AvFlagConstrainedAuth uint32 = 0x00000001
102→	// AvFlagMICPresent：AUTHENTICATE_MESSAGE 里带了 MIC 字段，服务端**必须**校验。
103→	AvFlagMICPresent uint32 = 0x00000002
104→	// AvFlagUntrustedSPN：客户端提供的 target SPN 来自不可信来源。
105→	AvFlagUntrustedSPN uint32 = 0x00000004
106→)
107→
108→// AvPair 是一条 AV_PAIR：AvId(2) || AvLen(2) || Value。
109→type AvPair struct {
110→	ID    AvID
111→	Value []byte
112→}
113→
114→// AvPairs 是 AV_PAIR 列表（不含结尾的 MsvAvEOL，编码时自动补）。
115→type AvPairs []AvPair
116→
117→var (
118→	// ErrNTLMTruncated 表示消息被截断或长度字段越界。
119→	ErrNTLMTruncated = errors.New("auth: NTLM message truncated")
120→	// ErrNTLMSignature 表示缺少 "NTLMSSP\\0" 魔数。
121→	ErrNTLMSignature = errors.New("auth: bad NTLMSSP signature")
122→	// ErrNTLMMessageType 表示消息类型不是期望值。
123→	ErrNTLMMessageType = errors.New("auth: unexpected NTLM message type")
124→	// ErrNTLMTooLarge 表示消息超过 maxNTLMMessageSize。
125→	ErrNTLMTooLarge = errors.New("auth: NTLM message too large")
126→)
127→
128→// Encode 把 AV_PAIR 列表编码为字节串，自动追加 MsvAvEOL 终止对。
129→func (p AvPairs) Encode() []byte {
130→	n := 4 // EOL
131→	for _, av := range p {
132→		n += 4 + len(av.Value)
133→	}
134→	out := make([]byte, 0, n)
135→	var hdr [4]byte
136→	for _, av := range p {
137→		binary.LittleEndian.PutUint16(hdr[0:], uint16(av.ID))
138→		binary.LittleEndian.PutUint16(hdr[2:], uint16(len(av.Value)))
139→		out = append(out, hdr[:]...)
140→		out = append(out, av.Value...)
141→	}
142→	return append(out, 0, 0, 0, 0) // MsvAvEOL, AvLen=0
143→}
144→
145→// ParseAvPairs 解析 AV_PAIR 列表。遇到 MsvAvEOL 结束，EOL 不进入结果。
146→//
147→// 先校验长度再切片，任何越界都返回 ErrNTLMTruncated（不 panic）。
148→func ParseAvPairs(b []byte) (AvPairs, error) {
149→	var out AvPairs
150→	for {
151→		if len(b) < 4 {
152→			// 缺少 EOL 也当作截断，避免默默接受畸形输入。
153→			return nil, ErrNTLMTruncated
154→		}
155→		id := AvID(binary.LittleEndian.Uint16(b[0:]))
156→		n := int(binary.LittleEndian.Uint16(b[2:]))
157→		if len(b) < 4+n {
158→			return nil, ErrNTLMTruncated
159→		}
160→		if id == MsvAvEOL {
161→			return out, nil
162→		}
163→		v := make([]byte, n)
164→		copy(v, b[4:4+n])
165→		out = append(out, AvPair{ID: id, Value: v})
166→		b = b[4+n:]
167→	}
168→}
169→
170→// Get 返回第一个匹配 id 的值。
171→func (p AvPairs) Get(id AvID) ([]byte, bool) {
172→	for _, av := range p {
173→		if av.ID == id {
174→			return av.Value, true
175→		}
176→	}
177→	return nil, false
178→}
179→
180→// Version 是 NTLM 的 VERSION 结构（MS-NLMP §2.2.2.10），仅用于调试展示。
181→type Version struct {
182→	Major        uint8
183→	Minor        uint8
184→	Build        uint16
185→	NTLMRevision uint8
186→}
187→
188→// NTLMRevisionCurrent 即 NTLMSSP_REVISION_W2K3 = 0x0F（MS-NLMP §2.2.2.10）。
189→const NTLMRevisionCurrent uint8 = 0x0F
190→
191→func (v Version) encode(dst []byte) {
192→	_ = dst[7]
193→	dst[0] = v.Major
194→	dst[1] = v.Minor
195→	binary.LittleEndian.PutUint16(dst[2:], v.Build)
196→	dst[4], dst[5], dst[6] = 0, 0, 0
197→	dst[7] = v.NTLMRevision
198→}
199→
200→func decodeVersion(b []byte) Version {
201→	if len(b) < 8 {
202→		return Version{}
203→	}
204→	return Version{
205→		Major:        b[0],
206→		Minor:        b[1],
207→		Build:        binary.LittleEndian.Uint16(b[2:]),
208→		NTLMRevision: b[7],
209→	}
210→}
211→
212→// ---------------------------------------------------------------- payload 三元组
213→
214→// field 描述一个 payload 三元组。
215→type field struct {
216→	Len    uint16
217→	MaxLen uint16
218→	Offset uint32
219→}
220→
221→func readField(b []byte, off int) field {
222→	return field{
223→		Len:    binary.LittleEndian.Uint16(b[off:]),
224→		MaxLen: binary.LittleEndian.Uint16(b[off+2:]),
225→		Offset: binary.LittleEndian.Uint32(b[off+4:]),
226→	}
227→}
228→
229→func writeField(b []byte, off int, n int, payloadOff int) {
230→	binary.LittleEndian.PutUint16(b[off:], uint16(n))
231→	binary.LittleEndian.PutUint16(b[off+2:], uint16(n))
232→	binary.LittleEndian.PutUint32(b[off+4:], uint32(payloadOff))
233→}
234→
235→// slice 按三元组取出 payload，越界返回 ErrNTLMTruncated。
236→func (f field) slice(msg []byte) ([]byte, error) {
237→	if f.Len == 0 {
238→		return nil, nil
239→	}
240→	end := uint64(f.Offset) + uint64(f.Len)
241→	if uint64(f.Offset) > uint64(len(msg)) || end > uint64(len(msg)) {
242→		return nil, ErrNTLMTruncated
243→	}
244→	out := make([]byte, f.Len)
245→	copy(out, msg[f.Offset:end])
246→	return out, nil
247→}
248→
249→// ---------------------------------------------------------------- 字符串编解码
250→
251→// utf16le 把 Go 字符串编码为 UTF-16LE 字节串。
252→func utf16le(s string) []byte {
253→	u := utf16.Encode([]rune(s))
254→	out := make([]byte, len(u)*2)
255→	for i, v := range u {
256→		binary.LittleEndian.PutUint16(out[i*2:], v)
257→	}
258→	return out
259→}
260→
261→// fromUTF16LE 解码 UTF-16LE 字节串。长度为奇数时丢弃末尾半个码元。
262→func fromUTF16LE(b []byte) string {
263→	n := len(b) / 2
264→	u := make([]uint16, n)
265→	for i := 0; i < n; i++ {
266→		u[i] = binary.LittleEndian.Uint16(b[i*2:])
267→	}
268→	return string(utf16.Decode(u))
269→}
270→
271→// decodeString 按 flags 里的 UNICODE 位决定用 UTF-16LE 还是 OEM(当作 Latin-1/ASCII)。
272→func decodeString(b []byte, flags NegotiateFlags) string {
273→	if flags.Has(NegotiateUnicode) {
274→		return fromUTF16LE(b)
275→	}
276→	return string(b)
277→}
278→
279→// ---------------------------------------------------------------- 消息公共头
280→
281→// MessageType 返回 NTLM 消息的类型，同时校验魔数与最小长度。
282→func MessageType(b []byte) (uint32, error) {
283→	if len(b) > maxNTLMMessageSize {
284→		return 0, ErrNTLMTooLarge
285→	}
286→	if len(b) < 12 {
287→		return 0, ErrNTLMTruncated
288→	}
289→	for i, c := range ntlmSignature {
290→		if b[i] != c {
291→			return 0, ErrNTLMSignature
292→		}
293→	}
294→	return binary.LittleEndian.Uint32(b[8:]), nil
295→}
296→
297→// IsNTLMSSP 报告 buffer 是否以 "NTLMSSP\0" 开头（裸 NTLM，无 SPNEGO 外壳）。
298→func IsNTLMSSP(b []byte) bool {
299→	if len(b) < len(ntlmSignature) {
300→		return false
301→	}
302→	for i, c := range ntlmSignature {
303→		if b[i] != c {
304→			return false
305→		}
306→	}
307→	return true
308→}
309→
310→func putHeader(b []byte, msgType uint32) {
311→	copy(b, ntlmSignature[:])
312→	binary.LittleEndian.PutUint32(b[8:], msgType)
313→}
314→
315→// ---------------------------------------------------------------- NEGOTIATE
316→
317→// NegotiateMessage 是 NTLM NEGOTIATE_MESSAGE（Type 1，MS-NLMP §2.2.1.1）。
318→type NegotiateMessage struct {
319→	Flags       NegotiateFlags
320→	Domain      string
321→	Workstation string
322→	Version     Version
323→}
324→
325→// ParseNegotiateMessage 解析 Type 1。
326→//
327→// 注意：真实客户端（含 Windows）可能只发到 Flags 为止（16 字节）就结束，
328→// 因此 Domain/Workstation/Version 都按"可选"处理。
329→func ParseNegotiateMessage(b []byte) (*NegotiateMessage, error) {
330→	t, err := MessageType(b)
331→	if err != nil {
332→		return nil, err
333→	}
334→	if t != MsgTypeNegotiate {
335→		return nil, ErrNTLMMessageType
336→	}
337→	if len(b) < 16 {
338→		return nil, ErrNTLMTruncated
339→	}
340→	m := &NegotiateMessage{Flags: NegotiateFlags(binary.LittleEndian.Uint32(b[12:]))}
341→	if len(b) >= 24 {
342→		f := readField(b, 16)
343→		v, err := f.slice(b)
344→		if err != nil {
345→			return nil, err
346→		}
347→		// Type 1 的 Domain/Workstation 恒为 OEM 字符串（MS-NLMP §2.2.1.1）。
348→		m.Domain = string(v)
349→	}
350→	if len(b) >= 32 {
351→		f := readField(b, 24)
352→		v, err := f.slice(b)
353→		if err != nil {
354→			return nil, err
355→		}
356→		m.Workstation = string(v)
357→	}
358→	if len(b) >= negotiateHeaderSize && m.Flags.Has(NegotiateVersion) {
359→		m.Version = decodeVersion(b[32:])
360→	}
361→	return m, nil
362→}
363→
364→// Marshal 编码 Type 1。服务端不需要它，主要供测试与将来的客户端侧使用。
365→func (m *NegotiateMessage) Marshal() []byte {
366→	domain := []byte(m.Domain)
367→	ws := []byte(m.Workstation)
368→	out := make([]byte, negotiateHeaderSize+len(domain)+len(ws))
369→	putHeader(out, MsgTypeNegotiate)
370→	binary.LittleEndian.PutUint32(out[12:], uint32(m.Flags))
371→	off := negotiateHeaderSize
372→	writeField(out, 16, len(domain), off)
373→	copy(out[off:], domain)
374→	off += len(domain)
375→	writeField(out, 24, len(ws), off)
376→	copy(out[off:], ws)
377→	m.Version.encode(out[32:])
378→	return out
379→}
380→
381→// ---------------------------------------------------------------- CHALLENGE
382→
383→// ChallengeMessage 是 NTLM CHALLENGE_MESSAGE（Type 2，MS-NLMP §2.2.1.2）。
384→type ChallengeMessage struct {
385→	TargetName      string
386→	Flags           NegotiateFlags
387→	ServerChallenge [8]byte
388→	TargetInfo      AvPairs
389→	Version         Version
390→}
391→
392→// Marshal 编码 Type 2。
393→//
394→// 布局（全部小端）：固定头 56 字节 + payload。
395→// payload 顺序为 TargetName、TargetInfo（与 Windows 实际报文一致）。
396→func (m *ChallengeMessage) Marshal() []byte {
397→	flags := m.Flags
398→	var name []byte
399→	if flags.Has(NegotiateUnicode) {
400→		name = utf16le(m.TargetName)
401→	} else {
402→		name = []byte(m.TargetName)
403→	}
404→	var info []byte
405→	if len(m.TargetInfo) > 0 {
406→		info = m.TargetInfo.Encode()
407→	}
408→
409→	out := make([]byte, challengeHeaderSize+len(name)+len(info))
410→	putHeader(out, MsgTypeChallenge)
411→
412→	off := challengeHeaderSize
413→	writeField(out, 12, len(name), off)
414→	copy(out[off:], name)
415→	off += len(name)
416→
417→	binary.LittleEndian.PutUint32(out[20:], uint32(flags))
418→	copy(out[24:], m.ServerChallenge[:])
419→	// out[32:40] Reserved 恒为 0。
420→	writeField(out, 40, len(info), off)
421→	copy(out[off:], info)
422→
423→	m.Version.encode(out[48:])
424→	return out
425→}
426→
427→// ParseChallengeMessage 解析 Type 2（服务端不需要，供测试与客户端侧使用）。
428→func ParseChallengeMessage(b []byte) (*ChallengeMessage, error) {
429→	t, err := MessageType(b)
430→	if err != nil {
431→		return nil, err
432→	}
433→	if t != MsgTypeChallenge {
434→		return nil, ErrNTLMMessageType
435→	}
436→	if len(b) < challengeHeaderSize {
437→		return nil, ErrNTLMTruncated
438→	}
439→	m := &ChallengeMessage{Flags: NegotiateFlags(binary.LittleEndian.Uint32(b[20:]))}
440→	nameBytes, err := readField(b, 12).slice(b)
441→	if err != nil {
442→		return nil, err
443→	}
444→	m.TargetName = decodeString(nameBytes, m.Flags)
445→	copy(m.ServerChallenge[:], b[24:32])
446→	infoBytes, err := readField(b, 40).slice(b)
447→	if err != nil {
448→		return nil, err
449→	}
450→	if len(infoBytes) > 0 {
451→		if m.TargetInfo, err = ParseAvPairs(infoBytes); err != nil {
452→			return nil, err
453→		}
454→	}
455→	m.Version = decodeVersion(b[48:])
456→	return m, nil
457→}
458→
459→// ---------------------------------------------------------------- AUTHENTICATE
460→
461→// AuthenticateMessage 是 NTLM AUTHENTICATE_MESSAGE（Type 3，MS-NLMP §2.2.1.3）。
462→type AuthenticateMessage struct {
463→	LMResponse                []byte
464→	NTResponse                []byte
465→	DomainName                string
466→	UserName                  string
467→	Workstation               string
468→	EncryptedRandomSessionKey []byte
469→	Flags                     NegotiateFlags
470→	Version                   Version
471→
472→	// MICPresent 表示消息里存在 MIC 字段（由 payload 最小偏移 ≥ 88 判定）。
473→	MICPresent bool
474→	// MIC 是 16 字节校验值，MICPresent 为 false 时无意义。
475→	MIC [MICSize]byte
476→
477→	// raw 是消息原始字节的副本，MIC 校验需要（要把 MIC 字段清零后重算）。
478→	raw []byte
479→}
480→
481→// ParseAuthenticateMessage 解析 Type 3。
482→//
483→// MIC 是否存在无法从标志位判断，MS-NLMP §2.2.1.3 的做法是看 payload 的
484→// 最小偏移：≥ 88 说明固定头里给 MIC 留了位置。
485→func ParseAuthenticateMessage(b []byte) (*AuthenticateMessage, error) {
486→	t, err := MessageType(b)
487→	if err != nil {
488→		return nil, err
489→	}
490→	if t != MsgTypeAuthenticate {
491→		return nil, ErrNTLMMessageType
492→	}
493→	if len(b) < authenticateMinSize {
494→		return nil, ErrNTLMTruncated
495→	}
496→
497→	lmF := readField(b, 12)
498→	ntF := readField(b, 20)
499→	domF := readField(b, 28)
500→	userF := readField(b, 36)
501→	wsF := readField(b, 44)
502→	keyF := readField(b, 52)
503→
504→	m := &AuthenticateMessage{
505→		Flags: NegotiateFlags(binary.LittleEndian.Uint32(b[60:])),
506→	}
507→	if m.LMResponse, err = lmF.slice(b); err != nil {
508→		return nil, err
509→	}
510→	if m.NTResponse, err = ntF.slice(b); err != nil {
511→		return nil, err
512→	}
513→	dom, err := domF.slice(b)
514→	if err != nil {
515→		return nil, err
516→	}
517→	user, err := userF.slice(b)
518→	if err != nil {
519→		return nil, err
520→	}
521→	ws, err := wsF.slice(b)
522→	if err != nil {
523→		return nil, err
524→	}
525→	if m.EncryptedRandomSessionKey, err = keyF.slice(b); err != nil {
526→		return nil, err
527→	}
528→	m.DomainName = decodeString(dom, m.Flags)
529→	m.UserName = decodeString(user, m.Flags)
530→	m.Workstation = decodeString(ws, m.Flags)
531→
532→	// payload 最小偏移决定固定头实际长度。
533→	minOff := len(b)
534→	for _, f := range []field{lmF, ntF, domF, userF, wsF, keyF} {
535→		if f.Len > 0 && int(f.Offset) < minOff {
536→			minOff = int(f.Offset)
537→		}
538→	}
539→	if minOff >= authenticateVersionSize && len(b) >= authenticateVersionSize {
540→		m.Version = decodeVersion(b[64:])
541→	}
542→	if minOff >= authenticateMICSize && len(b) >= authenticateMICSize {
543→		m.MICPresent = true
544→		copy(m.MIC[:], b[micOffset:micOffset+MICSize])
545→	}
546→
547→	m.raw = make([]byte, len(b))
548→	copy(m.raw, b)
549→	return m, nil
550→}
551→
552→// Raw 返回消息原始字节（只读，调用方不得修改）。
553→func (m *AuthenticateMessage) Raw() []byte { return m.raw }
554→
555→// rawWithZeroMIC 返回把 MIC 字段清零后的消息副本，用于 MIC 校验。
556→func (m *AuthenticateMessage) rawWithZeroMIC() []byte {
557→	out := make([]byte, len(m.raw))
558→	copy(out, m.raw)
559→	if m.MICPresent && len(out) >= authenticateMICSize {
560→		for i := micOffset; i < micOffset+MICSize; i++ {
561→			out[i] = 0
562→		}
563→	}
564→	return out
565→}
566→
567→// IsAnonymous 报告这是不是匿名（null session）认证。
568→//
569→// MS-NLMP §3.2.5.1.2：UserName 为空且 NtChallengeResponse 长度为 0
570→// （某些客户端会带一个长度为 1 的 LM 响应）。
571→func (m *AuthenticateMessage) IsAnonymous() bool {
572→	if m.Flags.Has(NegotiateAnonymous) {
573→		return true
574→	}
575→	return m.UserName == "" && len(m.NTResponse) == 0
576→}
577→
578→// Marshal 编码 Type 3（供测试与客户端侧使用）。
579→//
580→// 布局：固定头（含 Version 与 MIC 时为 88 字节）+ payload。
581→// payload 顺序 Domain、User、Workstation、LM、NT、SessionKey，与 Windows 一致。
582→func (m *AuthenticateMessage) Marshal() []byte {
583→	enc := func(s string) []byte {
584→		if m.Flags.Has(NegotiateUnicode) {
585→			return utf16le(s)
586→		}
587→		return []byte(s)
588→	}
589→	dom, user, ws := enc(m.DomainName), enc(m.UserName), enc(m.Workstation)
590→
591→	hdr := authenticateVersionSize
592→	if m.MICPresent {
593→		hdr = authenticateMICSize
594→	}
595→	total := hdr + len(dom) + len(user) + len(ws) +
596→		len(m.LMResponse) + len(m.NTResponse) + len(m.EncryptedRandomSessionKey)
597→	out := make([]byte, total)
598→	putHeader(out, MsgTypeAuthenticate)
599→	binary.LittleEndian.PutUint32(out[60:], uint32(m.Flags))
600→	m.Version.encode(out[64:])
601→	if m.MICPresent {
602→		copy(out[micOffset:], m.MIC[:])
603→	}
604→
605→	off := hdr
606→	put := func(fieldOff int, v []byte) {
607→		writeField(out, fieldOff, len(v), off)
608→		copy(out[off:], v)
609→		off += len(v)
610→	}
611→	put(28, dom)
612→	put(36, user)
613→	put(44, ws)
614→	put(12, m.LMResponse)
615→	put(20, m.NTResponse)
616→	put(52, m.EncryptedRandomSessionKey)
617→	return out
618→}
