567→// IsAnonymous 报告这是不是匿名（null session）认证。
568→//
569→// MS-NLMP §3.2.5.1.2：UserName 为空且 NtChallengeResponse 长度为 0
570→// （某些客户端会带一个长度为 1 的 LM 响应）。
571→func (m *AuthenticateMessage) IsAnonymous() bool {
572→	if m.Flags.Has(NegotiateAnonymous) {
573→		return true
574→	}
575→	return m.UserName == "" && len(m.NTResponse) == 0
576→}
