578→// Marshal 编码 Type 3（供测试与客户端侧使用）。
579→//
580→// 布局：固定头（含 Version 与 MIC 时为 88 字节）+ payload。
581→// payload 顺序 Domain、User、Workstation、LM、NT、SessionKey，与 Windows 一致。
582→func (m *AuthenticateMessage) Marshal() []byte {
583→	enc := func(s string) []byte {
584→		if m.Flags.Has(NegotiateUnicode) {
585→			return utf16le(s)
586→		}
587→		return []byte(s)
588→	}
589→	dom, user, ws := enc(m.DomainName), enc(m.UserName), enc(m.Workstation)
590→
591→	hdr := authenticateVersionSize
592→	if m.MICPresent {
593→		hdr = authenticateMICSize
594→	}
595→	total := hdr + len(dom) + len(user) + len(ws) +
596→		len(m.LMResponse) + len(m.NTResponse) + len(m.EncryptedRandomSessionKey)
597→	out := make([]byte, total)
598→	putHeader(out, MsgTypeAuthenticate)
599→	binary.LittleEndian.PutUint32(out[60:], uint32(m.Flags))
600→	m.Version.encode(out[64:])
601→	if m.MICPresent {
602→		copy(out[micOffset:], m.MIC[:])
603→	}
604→
605→	off := hdr
606→	put := func(fieldOff int, v []byte) {
607→		writeField(out, fieldOff, len(v), off)
608→		copy(out[off:], v)
609→		off += len(v)
610→	}
611→	put(28, dom)
612→	put(36, user)
613→	put(44, ws)
614→	put(12, m.LMResponse)
615→	put(20, m.NTResponse)
616→	put(52, m.EncryptedRandomSessionKey)
617→	return out
618→}
